CREATE TABLE el_custom_fields(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),entity TEXT NOT NULL CHECK(entity IN ('students','guardians','teachers','courses','groups','classrooms')),field_key TEXT NOT NULL,label TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('text','number','date','select','boolean')),options_json TEXT NOT NULL DEFAULT '[]',required INTEGER NOT NULL DEFAULT 0 CHECK(required IN (0,1)),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),created_at INTEGER NOT NULL,UNIQUE(org_id,entity,field_key),UNIQUE(org_id,id));
CREATE INDEX el_custom_fields_entity ON el_custom_fields(org_id,entity,status,created_at);
CREATE TABLE el_custom_values(org_id TEXT NOT NULL,field_id TEXT NOT NULL,record_id TEXT NOT NULL,value_json TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(org_id,field_id,record_id),FOREIGN KEY(org_id,field_id) REFERENCES el_custom_fields(org_id,id));
CREATE INDEX el_custom_values_record ON el_custom_values(org_id,record_id,field_id);
CREATE TRIGGER el_custom_field_cap BEFORE INSERT ON el_custom_fields WHEN (SELECT count(*) FROM el_custom_fields WHERE org_id=NEW.org_id)>=200 BEGIN SELECT RAISE(ABORT,'Custom field limit reached'); END;
-- Preserve definition type/entity identity and reject raced archive writes.
CREATE TRIGGER el_custom_definition_identity BEFORE UPDATE ON el_custom_fields WHEN NEW.entity<>OLD.entity OR NEW.field_key<>OLD.field_key OR NEW.type<>OLD.type OR NEW.options_json<>OLD.options_json OR NEW.org_id<>OLD.org_id BEGIN SELECT RAISE(ABORT,'Custom field type and identity are immutable'); END;
CREATE TRIGGER el_custom_value_insert BEFORE INSERT ON el_custom_values WHEN NOT EXISTS(SELECT 1 FROM el_custom_fields f WHERE f.id=NEW.field_id AND f.org_id=NEW.org_id AND f.status='active') BEGIN SELECT RAISE(ABORT,'Custom field is archived'); END;
CREATE TRIGGER el_custom_value_update BEFORE UPDATE ON el_custom_values WHEN NOT EXISTS(SELECT 1 FROM el_custom_fields f WHERE f.id=NEW.field_id AND f.org_id=NEW.org_id AND f.status='active') BEGIN SELECT RAISE(ABORT,'Custom field is archived'); END;
CREATE TRIGGER el_custom_cleanup_students AFTER DELETE ON el_students BEGIN DELETE FROM el_custom_values WHERE org_id=OLD.org_id AND record_id=OLD.id AND field_id IN(SELECT id FROM el_custom_fields WHERE org_id=OLD.org_id AND entity='students'); END;
CREATE TRIGGER el_custom_cleanup_guardians AFTER DELETE ON el_guardians BEGIN DELETE FROM el_custom_values WHERE org_id=OLD.org_id AND record_id=OLD.id AND field_id IN(SELECT id FROM el_custom_fields WHERE org_id=OLD.org_id AND entity='guardians'); END;
CREATE TRIGGER el_custom_cleanup_teachers AFTER DELETE ON el_teachers BEGIN DELETE FROM el_custom_values WHERE org_id=OLD.org_id AND record_id=OLD.id AND field_id IN(SELECT id FROM el_custom_fields WHERE org_id=OLD.org_id AND entity='teachers'); END;
CREATE TRIGGER el_custom_cleanup_courses AFTER DELETE ON el_courses BEGIN DELETE FROM el_custom_values WHERE org_id=OLD.org_id AND record_id=OLD.id AND field_id IN(SELECT id FROM el_custom_fields WHERE org_id=OLD.org_id AND entity='courses'); END;
CREATE TRIGGER el_custom_cleanup_groups AFTER DELETE ON el_groups BEGIN DELETE FROM el_custom_values WHERE org_id=OLD.org_id AND record_id=OLD.id AND field_id IN(SELECT id FROM el_custom_fields WHERE org_id=OLD.org_id AND entity='groups'); END;
CREATE TRIGGER el_custom_cleanup_classrooms AFTER DELETE ON el_classrooms BEGIN DELETE FROM el_custom_values WHERE org_id=OLD.org_id AND record_id=OLD.id AND field_id IN(SELECT id FROM el_custom_fields WHERE org_id=OLD.org_id AND entity='classrooms'); END;
